const layerPaths = (layers, rotation = 0) => layers.map(layer => `<path transform="translate(${layer.x ?? 0} ${layer.y ?? 0}) rotate(${layerRotation(layer, rotation)}) scale(${layer.scale ?? 1} ${(layer.scale ?? 1) * (layer.scaleY ?? 1)})" d="${layer.path}" fill="${layer.fill ?? 'none'}"${layer.fillRule ? ` fill-rule="${layer.fillRule}"` : ''} stroke="${layer.width ? layer.color : 'none'}" stroke-width="${layer.width}" stroke-linecap="${layer.cap ?? 'round'}" stroke-linejoin="round"${layer.dash ? ` stroke-dasharray="${layer.dash.join(' ')}"` : ''}/>`).join('');
